#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-10

# strict-mode: opt-out this harness counts failures and reports a summary, so
# `-e` would abort on the first failing assertion and hide the rest. Same shape
# as tests/security/test-npm-audit.sh. `set -uo pipefail` is set below.
#
# =============================================================================
# The hooks manifest mirror must not carry devDependencies (#3971)
# =============================================================================
# plugins/ork/hooks/package.json is a TRACKED generated mirror of
# src/hooks/package.json, and it sits inside ci.yml's build-drift roster
# (`plugins/` minus only `plugins/ork/hooks/dist`). Dependabot edits the source
# manifest and never runs a build, so before #3971 every src/hooks bump left the
# mirror stale and failed the required Build check. The gate was correct; the
# automation could not satisfy it, and the lane was landable by hand only.
#
# scripts/build-plugins.sh now deletes `.devDependencies` from the mirror, so a
# devDep bump produces no mirror diff at all.
#
# This test is the ratchet. Two halves, and the second is the one that matters:
#
#   A. the shipped mirror carries no devDependencies, and still carries the
#      fields that ARE real (name/version/type/bin/engines), so a future
#      "just exclude the whole file" cannot pass by deleting everything;
#   B. a POSITIVE CONTROL that simulates the actual #3971 scenario: bump every
#      devDependency in a copy of the source manifest, run the same strip, and
#      assert the mirror is byte-identical. Without B this test would still
#      pass if the strip were removed and someone hand-edited the mirror once,
#      which is the failure mode that produced the issue in the first place.
# =============================================================================

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
cd "$REPO_ROOT"

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; NC=$'\033[0m'
PASS=0; FAIL=0
pass() { echo "  ${GREEN}PASS${NC} $1"; PASS=$((PASS + 1)); }
fail() { echo "  ${RED}FAIL${NC} $1"; FAIL=$((FAIL + 1)); }

MIRROR="plugins/ork/hooks/package.json"
SOURCE="src/hooks/package.json"

echo "=========================================="
echo "  hooks manifest mirror (#3971)"
echo "=========================================="

# ─── A. the shipped mirror ──────────────────────────────────────────
if [[ ! -f "$MIRROR" ]]; then
  fail "$MIRROR is missing (run npm run build)"
else
  if jq -e 'has("devDependencies")' "$MIRROR" >/dev/null 2>&1; then
    fail "$MIRROR still carries devDependencies — the #3971 strip did not run"
  else
    pass "$MIRROR carries no devDependencies"
  fi

  # Anti-vacuity: the strip must remove ONE field, not gut the manifest. If the
  # mirror were emptied or excluded outright, the check above would pass while
  # the plugin lost `type: module` and its bin mapping.
  MISSING=""
  for field in name version type bin engines; do
    jq -e --arg f "$field" 'has($f)' "$MIRROR" >/dev/null 2>&1 || MISSING="$MISSING $field"
  done
  if [[ -n "$MISSING" ]]; then
    fail "$MIRROR lost real fields:$MISSING (the strip must remove devDependencies only)"
  else
    pass "$MIRROR keeps name/version/type/bin/engines"
  fi
fi

# ─── B. positive control: a devDep bump must not move the mirror ────
if [[ ! -f "$SOURCE" ]]; then
  fail "$SOURCE is missing — cannot run the bump simulation"
else
  TMP="$(mktemp -d "${TMPDIR:-/tmp}/ork-mirror.XXXXXX")"
  trap 'rm -rf "$TMP"' EXIT

  # The strip as build-plugins.sh applies it, against the real source manifest
  # and against a copy with every devDependency bumped to a bogus version.
  jq 'del(.devDependencies)' "$SOURCE" > "$TMP/before.json"
  jq '(.devDependencies // {}) |= with_entries(.value = "^99.99.99") | del(.devDependencies)' \
     "$SOURCE" > "$TMP/after.json"

  # Guard the guard: if the source had no devDependencies at all, the two files
  # would match trivially and this control would prove nothing.
  DEV_COUNT=$(jq -r '(.devDependencies // {}) | length' "$SOURCE")
  if [[ "$DEV_COUNT" -eq 0 ]]; then
    fail "$SOURCE declares no devDependencies — the bump simulation is vacuous"
  elif diff -q "$TMP/before.json" "$TMP/after.json" >/dev/null 2>&1; then
    pass "bumping all $DEV_COUNT devDependencies produces an identical mirror"
  else
    fail "a devDependency bump still changes the mirror — #3971 is not closed"
    diff "$TMP/before.json" "$TMP/after.json" | head -10
  fi
fi

echo "=========================================="
echo "  Passed: $PASS  Failed: $FAIL"
echo "=========================================="
[[ $FAIL -eq 0 ]]
